import sympy

def build_instance(rng):
    integer = rng.randint(1, 1000)
    prime_factors = sympy.factorint(integer)
    num_divisors = 1
    for exponent in prime_factors.values():
        num_divisors *= exponent + 1
    check = len([d for d in range(1, integer + 1) if integer % d == 0])
    answer = num_divisors
    parameters = {'integer': integer}
    return (parameters, answer, check)



